from functools import singledispatch
from collections.abc import Iterable
@singledispatch
def render(value, verbose: bool = False) -> str:      # fallback registered for object
    return repr(value)

@render.register
def _(value: Iterable, verbose: bool = False) -> str:  # property: is iterable
    return ",".join(map(str, value))

render([1, 2, 3])            # -> '1,2,3' (list is a virtual subclass of Iterable)
render.dispatch(list)        # inspect which implementation wins
